void write_huffman_dictionary(std::ofstream &outfile, const std::unordered_map<unsigned char, std::string> &huffman_codes) {
    // Write the number of entries in the dictionary
    size_t size = huffman_codes.size();
    outfile.write(reinterpret_cast<const char*>(&size), sizeof(size));

    // Write each character, its code length, and its code
    for (const auto &entry : huffman_codes) {
        unsigned char character = entry.first;
        const std::string &code = entry.second;

        // Write the character
        outfile.write(reinterpret_cast<const char*>(&character), sizeof(unsigned char));

        // Write the length of the code
        unsigned char code_length = static_cast<unsigned char>(code.length());
        outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));

        // Write the code itself (bit by bit)
        // Pack 8 bits into each byte
        unsigned char buffer = 0;
        int bit_count = 0;

        for (char bit : code) {
            if (bit == '1') {
                buffer |= (1 << (7 - bit_count));
            }
            bit_count++;

            if (bit_count == 8) {
                outfile.write(reinterpret_cast<const char*>(&buffer), sizeof(buffer));
                buffer = 0;
                bit_count = 0;
            }
